import {SKU_IMAGE_LIMIT,skuEditIntent,skuImageName} from './sku-image-policy.js';
import {imageHeader,validateImageSize} from './textile-print-metadata.js';
import {saveBlob} from './textile-tools-image.js';
import {buildImageArchive} from './image-download.js';
import {saveAssetDialog} from './library-client.js';

// SKU images have their own draft. Product facts used by the other tools are untouched.
export function createSKUImageEditor({parent,lock,toast}){
  const root=document.createElement('section');root.id='skuEditor';root.hidden=true;
  root.innerHTML=`<div class="sku-toolbar"><h1>SKU 图片处理</h1><span id="skuSaved" role="status">正在读取草稿…</span><button id="skuDownload">下载当前图片</button><button id="skuZip">打包所选图片</button></div>
  <div class="sku-workspace"><aside class="ec-card sku-sources"><header class="ec-section-head"><h2>SKU 图片</h2><span id="skuCount">0 / 24</span></header><div class="sku-source-actions"><button id="skuUpload" class="ec-primary">＋ 批量上传</button><input id="skuFiles" type="file" accept="image/png,image/jpeg,image/webp" multiple hidden><button id="skuSelectAll">全选</button><button id="skuSelectNone">取消选择</button></div><div id="skuImages" class="sku-images"></div><div class="sku-source-footer"><span id="skuSelected">已选 0 张</span><button id="skuRemove">移除当前</button></div></aside>
  <section class="ec-card sku-preview"><header class="ec-section-head"><h2 id="skuCurrentName">图片预览</h2><span id="skuDimensions"></span></header><div class="sku-view-tabs"><button id="skuViewCurrent" aria-pressed="true">当前图片</button><button id="skuViewOriginal" aria-pressed="false">原图</button><button id="skuViewCandidate" aria-pressed="false" hidden>AI 候选</button></div><div id="skuStage" class="sku-stage"><img id="skuPreview" alt="当前 SKU 图片" hidden><div id="skuEmpty"><strong>直接从你的 SKU 图片开始</strong><p>批量上传，选图，写下修改要求。</p><button id="skuEmptyUpload">选择图片</button></div></div><footer class="sku-preview-footer"><span id="skuViewNote">原图直接显示，不添加版式。</span><div><button id="skuApply" hidden>采用当前候选</button><button id="skuRestore" hidden>恢复原图</button><button id="skuLibrary">保存到图库</button></div></footer></section>
  <aside class="sku-settings"><section class="ec-card"><header class="ec-section-head"><h2>AI 图片处理</h2><span class="ec-ai-dot">AI</span></header><div class="ec-card-body"><label>本次要求<textarea id="skuPrompt" maxlength="2000" placeholder="例如：清理背景杂物，保留床品原有花色与构图"></textarea></label><div class="sku-presets"><button data-sku-preset="清理背景中多余杂物，保留商品、原有花色与构图。">清理背景</button><button data-sku-preset="调整为柔和自然光，保留商品真实花色与现有构图，避免过曝。">优化光影</button><button data-sku-preset="改善图片清晰度与可见面料细节，保留原花型、工艺与文字，不编造新的细节。">改善清晰度</button></div><p class="sku-default-note">原图比例 · 默认不加边框和文字</p><button id="skuRunCurrent" class="ec-primary">AI 处理当前图片</button><button id="skuRunSelected">AI 处理所选图片（0）</button><button id="skuStop" hidden>停止后续处理</button><p class="ec-charge">点击处理后，所选图片与要求发送至当前图片服务，按张计费。</p><p id="skuStatus" role="status" aria-live="polite"></p><button id="skuCheck" hidden>仅检查未完成任务</button><progress id="skuProgress" hidden max="1" value="0"></progress></div></section>
  <section class="ec-card"><header class="ec-section-head"><h2>结果确认</h2><span id="skuResultsCount">0 张候选</span></header><div class="ec-card-body"><p>查看候选与原图，确认后采用。</p><button id="skuApplySelected">采用所选图片的候选</button><details class="sku-help"><summary>使用说明</summary><p>最多上传24张，每张32MB，整组256MB。上传、选图和恢复草稿不会调用AI。不需要填写商品名称和规格。</p><p>处理所选图片时，逐张使用相同要求；每张从当前已采用版本继续修改。候选不会自动覆盖原图。默认保留原比例，不进行规格卡片排版。边框、文字与装饰由你明确要求。</p><p>为适配接口，首次处理时参考副本长边最多2048像素；AI输出尺寸可能变化，导出使用实际结果尺寸，原始文件仍完整保留。AI可能改变细节，请核对花型与文字。</p><p>失败或刷新不会自动重试、不会自动提交剩余图片。请求状态不明时先检查任务；停止不能撤销服务已产生的费用。下载当前图片遵循预览版本，打包所选图片使用各图已采用版本。</p></details></div></section></aside></div>`;
  parent.append(root);
  const $=id=>root.querySelector('#'+id);
  const state={items:[],selected:[],current:null,prompt:'',view:'current',ready:false,busy:false,stop:false,pending:null};
  let dbPromise,saveChain=Promise.resolve(),progress='',saveTimer;
  const current=()=>state.items.find(i=>i.id===state.current);
  const pending=()=>!!state.pending;
  const blocked=()=>!state.ready||state.busy||pending();
  const status=(text,error=false)=>{$('skuStatus').textContent=text;$('skuStatus').dataset.error=String(error);};
  function db(){return dbPromise??=new Promise((resolve,reject)=>{const r=indexedDB.open('zhijing-sku-images-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('draft');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('草稿存储不可用'));});}
  function snapshot(){return {version:1,items:state.items.map(({url,thumbURL,...item})=>item),selected:[...state.selected],current:state.current,prompt:state.prompt,pending:state.pending};}
  async function persist(){clearTimeout(saveTimer);const value=snapshot();$('skuSaved').textContent='正在保存…';saveChain=saveChain.catch(()=>{}).then(async()=>{const store=await db();await new Promise((resolve,reject)=>{const tx=store.transaction('draft','readwrite');tx.objectStore('draft').put(value,'current');tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error);tx.onerror=()=>reject(tx.error);});});try{await saveChain;$('skuSaved').textContent='本机草稿已保存';}catch(e){$('skuSaved').textContent='草稿未保存，请先下载图片';throw e;}}
  function save(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(()=>{}),250);}
  function busy(value){state.busy=value;lock(value);controls();}
  async function request(url,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch(url,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});const data=await r.json();if(!r.ok)throw Object.assign(Error(data.error||'请求未完成'),{http:r.status});return data;}catch(e){if(controller.signal.aborted)throw Error('请求超时，任务状态尚未确认');if(e instanceof TypeError)throw Error('无法连接服务，请检查网络');if(e instanceof SyntaxError)throw Error('服务返回内容无法读取，请检查已有任务');throw e;}finally{clearTimeout(timer);}}
  function controls(){const item=current(),off=blocked();for(const n of root.querySelectorAll('#skuUpload,#skuFiles,#skuRemove,#skuSelectAll,#skuSelectNone,#skuPrompt,[data-sku-preset],#skuApply,#skuRestore,#skuApplySelected'))n.disabled=off;
    $('skuRunCurrent').disabled=off||!item||!state.prompt.trim();$('skuRunSelected').disabled=off||!state.selected.length||!state.prompt.trim();$('skuRunSelected').textContent='AI 处理所选图片（'+state.selected.length+'）';$('skuStop').hidden=!state.busy;$('skuStop').disabled=state.stop;$('skuCheck').hidden=!pending()||state.busy;
    $('skuDownload').disabled=state.busy||!item;$('skuZip').disabled=state.busy||!state.selected.length;$('skuLibrary').disabled=state.busy||!item;$('skuRemove').disabled=off||!item;$('skuApplySelected').disabled=off||!state.items.some(i=>state.selected.includes(i.id)&&i.candidate);
    $('skuSelected').textContent='已选 '+state.selected.length+' 张';$('skuCount').textContent=state.items.length+' / '+SKU_IMAGE_LIMIT;$('skuResultsCount').textContent=state.items.filter(i=>i.candidate).length+' 张候选';
    for(const n of root.querySelectorAll('.sku-item input'))n.disabled=off;
  }
  function version(item,view=state.view){return view==='original'?null:view==='candidate'?item.candidate:item.applied;}
  function preview(){const item=current(),result=item&&version(item);$('skuEmpty').hidden=!!item;$('skuPreview').hidden=!item;
    $('skuCurrentName').textContent=item?.name||'图片预览';$('skuDimensions').textContent=item?(result?.width||item.width)+' × '+(result?.height||item.height)+' px':'';
    if(item)$('skuPreview').src=result?.url||item.url;else $('skuPreview').removeAttribute('src');
    for(const [id,view]of [['skuViewCurrent','current'],['skuViewOriginal','original'],['skuViewCandidate','candidate']])$(id).setAttribute('aria-pressed',String(state.view===view));
    $('skuViewCandidate').hidden=!item?.candidate;$('skuApply').hidden=!item?.candidate;$('skuRestore').hidden=!item?.applied;
    $('skuViewNote').textContent=!item?'原图直接显示，不添加版式。':state.view==='candidate'?'AI 候选 · 尚未采用':state.view==='original'||!item.applied?'原始文件 · 未添加边框和文字':'已采用版本 · 原图仍保留';controls();
  }
  function renderList(){const list=$('skuImages');list.replaceChildren();for(const item of state.items){const card=document.createElement('article');card.className='sku-item';card.dataset.id=item.id;card.dataset.current=String(item.id===state.current);
      const check=document.createElement('input');check.type='checkbox';check.checked=state.selected.includes(item.id);check.setAttribute('aria-label','选择 '+item.name);check.onchange=()=>{state.selected=check.checked?[...state.selected,item.id]:state.selected.filter(id=>id!==item.id);save();controls();};
      const button=document.createElement('button');button.className='sku-thumbnail';const img=new Image();img.src=item.thumbURL;img.alt='';const label=document.createElement('span');label.textContent=item.name;const mark=document.createElement('small');mark.textContent=item.candidate?'待确认':item.applied?'已采用':item.status||'原图';button.append(img,label,mark);button.onclick=()=>{state.current=item.id;state.view=item.candidate?'candidate':'current';renderList();preview();save();};card.append(check,button);list.append(card);
    }controls();}
  function attachURLs(item){item.url=URL.createObjectURL(item.blob);item.thumbURL=URL.createObjectURL(item.thumb);return item;}
  async function decode(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>32*1024*1024)throw Error('请选择32MB以内的PNG、JPG或WebP');imageHeader(await file.arrayBuffer());const bitmap=await createImageBitmap(file);try{validateImageSize(bitmap.width,bitmap.height);const scale=Math.min(1,320/Math.max(bitmap.width,bitmap.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);const thumb=await new Promise(resolve=>c.toBlob(resolve,'image/png'));return attachURLs({id:crypto.randomUUID(),name:file.name.slice(0,120),blob:file,thumb,width:bitmap.width,height:bitmap.height,applied:null,candidate:null,docId:null,status:'原图'});}finally{bitmap.close();}}
  async function upload(files){if(blocked()||!files.length)return;const all=[...files];if(state.items.length+all.length>SKU_IMAGE_LIMIT)return toast('最多24张，请分批处理');if([...state.items.map(i=>i.blob),...all].reduce((n,f)=>n+f.size,0)>256*1024*1024)return toast('整组图片请控制在256MB以内');busy(true);const loaded=[];try{for(const file of all)loaded.push(await decode(file));state.items.push(...loaded);state.selected.push(...loaded.map(i=>i.id));state.current=loaded[0].id;state.view='current';renderList();preview();await persist();status('已加入 '+loaded.length+' 张原图，未调用 AI。');}catch(e){if(!loaded.some(i=>state.items.includes(i)))loaded.forEach(i=>{URL.revokeObjectURL(i.url);URL.revokeObjectURL(i.thumbURL);});status(e.message,true);}finally{busy(false);}}
  async function normalized(item){const bitmap=await createImageBitmap(item.blob);try{let edge=2048;for(let attempt=0;attempt<3;attempt++){const scale=Math.min(1,edge/Math.max(bitmap.width,bitmap.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);const data=c.toDataURL('image/png');if(data.length<13*1024*1024)return data;edge=Math.floor(edge*.75);}throw Error('图片转换后过大，请缩小后处理');}finally{bitmap.close();}}
  function applyDocument(item,doc,operationId){if(doc.id!==item.docId)throw Error('任务记录不匹配');const op=doc.operations.find(o=>o.id===operationId);if(!op)return false;item.status=op.status==='queued'?'排队中':op.status==='running'?'处理中':op.status==='cancelled'?'已停止':op.status==='error'?'处理失败':'待确认';
    const result=doc.versions.find(v=>v.id===operationId);if(result){const url='/api/free/documents/'+item.docId+'/images/'+result.id;if(result.url!==url)throw Error('结果图片地址无效');item.candidate={id:result.id,url,width:result.width,height:result.height};if(state.current===item.id)state.view='candidate';}
    renderList();preview();return !['queued','running'].includes(op.status);
  }
  async function waitForResult(item){const start=Date.now();while(state.pending){const p=state.pending;const {document:doc}=await request('/api/free/documents/'+item.docId);if(!p.operationId){const found=doc.operations.find(o=>!p.before.includes(o.id));if(!found)throw Error('提交结果尚不明确，请稍后仅检查任务；不会自动重复提交。');p.operationId=found.id;await persist();}
      if(state.stop&&doc.operations.some(o=>o.id===p.operationId&&['queued','running'].includes(o.status))){await request('/api/free/documents/'+item.docId+'/cancel',{});continue;}
      if(applyDocument(item,doc,p.operationId)){const op=doc.operations.find(o=>o.id===p.operationId);state.pending=null;await persist();if(op.status!=='done'||!doc.versions.some(v=>v.id===op.id))throw Error(op.status==='cancelled'?'已停止，原图保留。':op.message||'本张处理失败，后续图片未提交。');return;}
      if(Date.now()-start>15*60*1000)throw Error('仍在处理中，稍后可仅检查任务。');await new Promise(resolve=>setTimeout(resolve,1000));
    }}
  async function run(ids){if(blocked())return;try{skuEditIntent(state.prompt);}catch(e){return toast(e.message);}const items=ids.map(id=>state.items.find(i=>i.id===id)).filter(Boolean);if(!items.length)return;const brief=state.prompt;state.stop=false;busy(true);$('skuProgress').hidden=false;$('skuProgress').max=items.length;$('skuProgress').value=0;
    try{const service=await request('/api/status');if(!service.configured||!['sub2api','openai','compatible'].includes(service.provider))throw Error('请先在完整工作台的设置中连接支持图片编辑的服务');for(const [index,item]of items.entries()){if(state.stop)break;state.current=item.id;state.view='current';progress='第 '+(index+1)+' / '+items.length+' 张';status(progress+' · 正在准备图片…');renderList();preview();
        if(!item.docId){const image=await normalized(item);if(state.stop)break;const created=await request('/api/free/documents',{image,title:item.name});item.docId=created.document.id;await persist();}
        if(state.stop)break;const {document:doc}=await request('/api/free/documents/'+item.docId);const active=doc.operations.find(o=>['queued','running'].includes(o.status));if(active){state.pending={itemId:item.id,operationId:active.id,before:[],phase:'waiting'};await persist();throw Error('这张图片已有任务，请先检查任务后再处理。');}
        // Persist intent BEFORE the paid request. Reload only checks its outcome, never resubmits.
        state.pending={itemId:item.id,operationId:null,before:doc.operations.map(o=>o.id),phase:'submitting'};await persist();if(state.stop){state.pending=null;await persist();break;}
        const submitted=await request('/api/free/documents/'+item.docId+'/edit',skuEditIntent(brief,item.applied?.id||'original'));state.pending.operationId=submitted.operationId;state.pending.phase='waiting';await persist();status(progress+' · 已提交，等待图片结果…');await waitForResult(item);$('skuProgress').value=index+1;
      }status(state.stop?'已停止后续处理，已完成候选保留。':'处理完成，请对比原图后采用候选。');
    }catch(e){status(e.message+(pending()?' 请点击“仅检查未完成任务”，不会自动重复计费。':''),true);}finally{busy(false);renderList();preview();save();}}
  async function check(){if(state.busy||!state.pending)return;busy(true);state.stop=false;try{const item=state.items.find(i=>i.id===state.pending.itemId);if(!item)throw Error('找不到任务原图');status('正在检查已有任务，不会提交新处理…');await waitForResult(item);status('任务已完成，请确认候选；剩余图片未自动提交。');}catch(e){status(e.message,true);}finally{busy(false);renderList();preview();save();}}
  async function stop(){state.stop=true;controls();status('正在停止，后续图片不会提交…');if(state.pending){const item=state.items.find(i=>i.id===state.pending.itemId);try{await request('/api/free/documents/'+item.docId+'/cancel',{});}catch{status('停止请求尚未确认，后续图片不会提交；请检查任务状态。',true);}}}
  async function apply(ids){if(blocked())return;busy(true);for(const item of state.items)if(ids.includes(item.id)&&item.candidate){item.applied=item.candidate;item.candidate=null;item.status='已采用';}state.view='current';renderList();preview();try{await persist();}catch(e){status(e.message,true);}finally{busy(false);}}
  async function output(item,view='current'){const result=version(item,view);if(!result)return {blob:item.blob,extension:item.blob.type==='image/jpeg'?'jpg':item.blob.type==='image/webp'?'webp':'png',edited:false};const r=await fetch(result.url);if(!r.ok)throw Error('结果图片暂时无法读取，原图仍保留');return {blob:await r.blob(),extension:'png',edited:true};}
  async function download(zip=false){if(state.busy)return;busy(true);try{if(zip){const entries=[];let total=0;for(const [index,item]of state.items.filter(i=>state.selected.includes(i.id)).entries()){const file=await output(item);total+=file.blob.size;if(total>256*1024*1024)throw Error('打包超过256MB，请分批下载');entries.push({path:skuImageName(item.name,index,file.edited)+'.'+file.extension,item:file.blob});}if(entries.length)saveBlob(await buildImageArchive(entries,b=>b.arrayBuffer()),'SKU图片.zip');}else{const item=current(),file=await output(item,state.view);saveBlob(file.blob,skuImageName(item.name,0,file.edited)+'.'+file.extension);}}catch(e){status(e.message,true);}finally{busy(false);}}
  $('skuUpload').onclick=$('skuEmptyUpload').onclick=()=>$('skuFiles').click();$('skuFiles').onchange=e=>{upload(e.target.files);e.target.value='';};
  $('skuSelectAll').onclick=()=>{state.selected=state.items.map(i=>i.id);renderList();save();};$('skuSelectNone').onclick=()=>{state.selected=[];renderList();save();};
  $('skuPrompt').oninput=e=>{state.prompt=e.target.value;controls();save();};for(const button of root.querySelectorAll('[data-sku-preset]'))button.onclick=()=>{$('skuPrompt').value=state.prompt=button.dataset.skuPreset;controls();save();};
  $('skuRunCurrent').onclick=()=>run([state.current]);$('skuRunSelected').onclick=()=>run([...state.selected]);$('skuCheck').onclick=check;$('skuStop').onclick=stop;
  for(const [id,view]of [['skuViewCurrent','current'],['skuViewOriginal','original'],['skuViewCandidate','candidate']])$(id).onclick=()=>{state.view=view;preview();};
  $('skuApply').onclick=()=>apply([state.current]);$('skuApplySelected').onclick=()=>apply(state.selected);$('skuRestore').onclick=async()=>{if(blocked())return;busy(true);current().applied=null;current().status='原图';state.view='current';renderList();preview();try{await persist();}catch(e){status(e.message,true);}finally{busy(false);}};
  $('skuRemove').onclick=()=>{if(blocked())return;const item=current();if(!item)return;URL.revokeObjectURL(item.url);URL.revokeObjectURL(item.thumbURL);state.items=state.items.filter(i=>i!==item);state.selected=state.selected.filter(id=>id!==item.id);state.current=state.items[0]?.id||null;state.view='current';renderList();preview();save();};
  $('skuDownload').onclick=()=>download();$('skuZip').onclick=()=>download(true);$('skuLibrary').onclick=async()=>{if(state.busy)return;busy(true);try{const item=current(),file=await output(item,state.view);await saveAssetDialog({blob:file.blob,name:item.name,kind:'product',source:'SKU图片处理'});}catch(e){status(e.message,true);}finally{busy(false);}};
  $('skuPreview').onerror=()=>status('预览无法读取，请检查服务连接；本机原图仍保留。',true);
  async function initialize(){try{const store=await db(),saved=await new Promise((resolve,reject)=>{const r=store.transaction('draft').objectStore('draft').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});if(saved?.version===1&&Array.isArray(saved.items)&&saved.items.length<=SKU_IMAGE_LIMIT){state.items=saved.items.map(attachURLs);state.selected=(saved.selected||[]).filter(id=>state.items.some(i=>i.id===id));state.current=state.items.some(i=>i.id===saved.current)?saved.current:state.items[0]?.id;state.prompt=saved.prompt||'';state.pending=saved.pending||null;$('skuPrompt').value=state.prompt;} $('skuSaved').textContent='本机草稿已就绪';if(pending())status('有未确认的处理任务，请点击“仅检查未完成任务”；不会自动提交新请求。');}catch(e){$('skuSaved').textContent='草稿暂不可用，请及时下载图片';}finally{state.ready=true;renderList();preview();}}
  window.addEventListener('pagehide',()=>{if(state.ready)persist().catch(()=>{});});initialize();
  return {activate(value){root.hidden=!value;},isBusy:()=>state.busy};
}
